  const OWNER_WA = '917338781288';
  const GINI_IMG = "data:image/jpeg;base64,";
  function saveCart() { localStorage.setItem('kvb_cart', JSON.stringify(cart)); }
  function loadCart() { try { return JSON.parse(localStorage.getItem('kvb_cart') || '[]'); } catch(e) { return []; } }

  let cart = loadCart();
  let currentOrderId = '';
  let toastTimer;

  function addGiniToCart() {
    addToCart('gini-tissue', 'Gini Tissue Saree', 599, 'Diwali Offer', GINI_IMG);
  }

  function addToCart(id, name, price, category, img) {
    const existing = cart.find(i => i.id === id);
    if (existing) { existing.qty++; }
    else { cart.push({ id, name, price, category, img, qty: 1 }); }
    saveCart();
    renderCart();
    document.getElementById('cartBadge').textContent = cart.reduce((s,i) => s+i.qty, 0);
    showToast(name);
    const btn = document.getElementById('giniAddBtn');
    if (btn) { btn.textContent = '✓ Added!'; setTimeout(() => btn.textContent = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:middle;margin-right:5px"><circle cx="9" cy="21" r="1"/><circle cx="20" cy="21" r="1"/><path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6"/></svg>Add to Cart', 2000); }
  }

  function showToast(name) {
    const t = document.getElementById('toast');
    t.textContent = '✓ Added: ' + (name.length > 35 ? name.slice(0,33)+'…' : name);
    t.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => t.classList.remove('show'), 2500);
  }

  function orderGiniWA() {
    const msg = 'Hello KVB Sarees! 🪔 I am interested in the Gini Tissue Saree – Deepavali Offer at ₹599. Please confirm availability and delivery details. Thank you! 🙏';
    window.open('https://wa.me/' + OWNER_WA + '?text=' + encodeURIComponent(msg), '_blank', 'noopener');
  }

  function updateQty(id, delta) {
    const item = cart.find(i => i.id === id);
    if (!item) return;
    item.qty += delta;
    if (item.qty <= 0) cart = cart.filter(i => i.id !== id);
    saveCart();
    renderCart();
    document.getElementById('cartBadge').textContent = cart.reduce((s,i)=>s+i.qty,0);
  }

  function removeItem(id) {
    cart = cart.filter(i => i.id !== id);
    saveCart();
    renderCart();
    document.getElementById('cartBadge').textContent = cart.reduce((s,i)=>s+i.qty,0);
  }

  function renderCart() {
    const body = document.getElementById('cartBody');
    const foot = document.getElementById('cartFoot');
    const total = cart.reduce((s,i) => s+i.price*i.qty, 0);
    document.getElementById('cartTotal').textContent = '₹' + total.toLocaleString('en-IN');
    if (cart.length === 0) {
      body.innerHTML = '<div class="cart-empty"><div class="ei"><svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="#ccc" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="9" cy="21" r="1"/><circle cx="20" cy="21" r="1"/><path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6"/></svg></div><p>Cart is empty.</p></div>';
      foot.style.display = 'none'; return;
    }
    foot.style.display = 'block';
    body.innerHTML = cart.map(item => `
      <div class="cart-item">
        ${item.img ? `<img class="ci-img" src="${item.img}" alt="${item.name}"/>` : `<div class="ci-img" style="display:flex;align-items:center;justify-content:center;font-size:1.8rem;background:#f5f5f5;">${item.emoji||'🥻'}</div>`}
        <div class="ci-info">
          <div class="ci-name">${item.name}</div>
          <div class="ci-meta">${item.category}</div>
          <div class="ci-price">₹${(item.price*item.qty).toLocaleString('en-IN')}</div>
          <div class="ci-qty">
            <button class="qty-btn" onclick="updateQty('${item.id}',-1)" aria-label="Decrease">−</button>
            <span class="qty-val">${item.qty}</span>
            <button class="qty-btn" onclick="updateQty('${item.id}',1)" aria-label="Increase">+</button>
          </div>
        </div>
        <button class="ci-remove" onclick="removeItem('${item.id}')" aria-label="Remove">✕</button>
      </div>`).join('');
  }

  function openCart() {
    document.getElementById('cartDrawer').classList.add('open');
    document.getElementById('cartOverlay').classList.add('show');
  }
  function closeCart() {
    document.getElementById('cartDrawer').classList.remove('open');
    document.getElementById('cartOverlay').classList.remove('show');
  }

  function generateOrderId() {
    const d = new Date();
    return 'KVB-' + d.getFullYear().toString().slice(2) + String(d.getMonth()+1).padStart(2,'0') + String(d.getDate()).padStart(2,'0') + '-' + (Math.floor(Math.random()*9000)+1000);
  }

  function placeOrder() {
    if (!cart.length) return;
    currentOrderId = generateOrderId();
    const total = cart.reduce((s,i)=>s+i.price*i.qty,0);
    document.getElementById('orderIdDisplay').textContent = currentOrderId;
    document.getElementById('orderTotalDisplay').textContent = '₹' + total.toLocaleString('en-IN');
    document.getElementById('orderSummaryLines').innerHTML = cart.map((item,idx) => `
      <div class="order-line">
        <div class="oname">${idx+1}. ${item.name}<br/><span class="oqty">${item.category} × ${item.qty}</span></div>
        <div class="oprice">₹${(item.price*item.qty).toLocaleString('en-IN')}</div>
      </div>`).join('');
    closeCart();
    document.getElementById('orderModal').classList.add('show');
  }

  function closeOrderModal() {
    document.getElementById('orderModal').classList.remove('show');
    openCart();
  }

  function copyOrderId() {
    navigator.clipboard.writeText(currentOrderId).then(() => {
      const btn = document.querySelector('.copy-btn');
      btn.textContent = '✅ Copied!';
      setTimeout(() => btn.textContent = '📋 Copy ID', 2000);
    });
  }

  function sendOrderWA() {
    const now = new Date();
    const total = cart.reduce((s,i)=>s+i.price*i.qty,0);
    const lines = cart.map((item,i) => `  ${i+1}. ${item.name} (${item.category}) × ${item.qty} — ₹${(item.price*item.qty).toLocaleString('en-IN')}`).join('\n');
    const msg = `🛍️ *New Order — KVB Sarees*\n\n📋 *Order ID:* ${currentOrderId}\n📅 *Date:* ${now.toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'})}\n\n🧵 *Items:*\n${lines}\n\n💰 *Total: ₹${total.toLocaleString('en-IN')}*\n\nPlease confirm my order. Thank you! 🙏`;
    window.open('https://wa.me/' + OWNER_WA + '?text=' + encodeURIComponent(msg), '_blank', 'noopener');
    cart = []; saveCart(); renderCart();
    document.getElementById('cartBadge').textContent = '0';
    document.getElementById('orderModal').classList.remove('show');
  }

  renderCart();
  document.getElementById('cartBadge').textContent = cart.reduce((s,i)=>s+i.qty,0) || '0';
  document.addEventListener('keydown', e => { if (e.key==='Escape') { closeCart(); } });
